{
  "findings": [
    {
      "check_id": "CKV_AWS_16",
      "title": "RDS instance storage encryption is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "HIGH",
      "explanation": "The 'storage_encrypted' attribute is missing, defaulting to false. This means data at rest in the RDS instance is not encrypted, violating security best practices and compliance requirements."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "RDS instance deletion protection is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The 'deletion_protection' attribute is missing, defaulting to false. This allows accidental or malicious deletion of the database instance without safeguards."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = \"false\"\n  storage_encrypted = true\n  deletion_protection = true\n}",
  "fix_summary": "Added 'storage_encrypted = true' to enable encryption at rest for the RDS instance. Added 'deletion_protection = true' to prevent accidental deletion of the database."
}
